  'monitor.tip.load': 'Load trung bình 1 / 5 / 15 phút. % chuẩn hoá theo số CPU: 100% = mọi core bận; server bận có thể vượt 100%.',
  'monitor.tip.cpu': '% CPU đang bận thật = 100 − idle − iowait (đo từ /proc/stat giữa 2 lần poll).',
  'monitor.tip.ram': '% RAM đã dùng (đã trừ cache/buffer đòi lại được — MemAvailable).',
  'monitor.tip.disk': '% đầy của phân vùng đầy nhất (bỏ tmpfs). Tên mount hiện cạnh nhãn.',
  'monitor.tip.us': 'us — %CPU chạy code ứng dụng (user). Cao = app đang thật sự ăn CPU.',
  'monitor.tip.sy': 'sy — %CPU chạy trong kernel (system): syscall, xử lý mạng, I/O. Cao bất thường thường do quá nhiều kết nối/tiến trình.',
  'monitor.tip.wa': 'wa — %CPU ngồi CHỜ đĩa (iowait). Cao = nghẽn disk chứ không phải thiếu CPU. Vàng khi ≥20.',
  'monitor.tip.st': 'st — %CPU bị hypervisor lấy cho VPS khác cùng máy vật lý (steal). ≥10 kéo dài = nhà cung cấp oversell, đáng khiếu nại.',
  'monitor.tip.r': 'r — số tiến trình đang XẾP HÀNG chờ CPU (run queue). Chỉ hiện khi lớn hơn số core = CPU không theo kịp.',
  'monitor.tip.swap': 'swap — MB swap đang dùng. RAM cạn nên hệ thống mượn đĩa làm RAM; app sẽ chậm thấy rõ.',
  'monitor.tip.net': 'Băng thông mạng: ↓ nhận / ↑ gửi (tổng mọi interface, trừ loopback).',
  'monitor.tip.conn': 'Số kết nối TCP đang mở (ESTABLISHED). Tăng vọt bất thường thường là bị bot/cào dữ liệu.',
  'monitor.tip.inode': '% inode đã dùng — hết inode là không tạo được file mới dù disk còn trống. Chỉ hiện khi ≥70%.',
  'monitor.tip.top': 'Tiến trình đang ăn CPU nhiều nhất lúc này.',
  'monitor.tip.svc': 'Uptime của service (thời gian từ lần service khởi động gần nhất) — khác uptime server ở góc trên: restart service không reset uptime server.',

