  'monitor.thresholdOffline': 'Alert when host goes offline',
  'monitor.thresholdsHint': 'Empty = metric disabled. Load is %/CPU so it CAN exceed 100% (300-400% is normal on busy servers) — set it to your baseline, e.g. 500. Alerts after ~9s sustained breach; repeats every 15 min while breached; recovers below threshold −5% for long enough.',
