  'monitor.metricConn': 'TCP connections',
  'monitor.alertOffline': '🔴 {host}: connection lost',
  'monitor.alertOnline': '✅ {host}: back online',
  'monitor.history': 'Metrics history',
  'monitor.historyTitle': 'History — {host}',
  'monitor.historyEmpty': 'No data in this range yet — run Monitoring for a few minutes and come back.',
  'monitor.range1h': '1 hour',
  'monitor.range24h': '24 hours',
  'monitor.loadNorm': '% per CPU',
  'monitor.historyInline': '1h history charts right on the card (click again to collapse)',
  'monitor.historyMore': '⤢ Details & 24h',
  'monitor.tip.load': 'Load average over 1 / 5 / 15 minutes. The % is normalized per CPU: 100% = every core busy; busy servers can exceed 100%.',
  'monitor.tip.cpu': '% CPU actually busy = 100 − idle − iowait (measured from /proc/stat between two polls).',
  'monitor.tip.ram': '% RAM used (reclaimable cache/buffers excluded — MemAvailable).',
  'monitor.tip.disk': 'Fullest real partition (tmpfs ignored). The mount point is shown next to the label.',
  'monitor.tip.us': 'us — %CPU running application code (user). High = the app itself is consuming CPU.',
  'monitor.tip.sy': 'sy — %CPU inside the kernel (system): syscalls, network, I/O handling. Unusually high often means too many connections/processes.',
  'monitor.tip.wa': 'wa — %CPU WAITING for disk (iowait). High = disk bottleneck, not a CPU shortage. Amber at ≥20.',
  'monitor.tip.st': 'st — %CPU stolen by the hypervisor for other VPS on the same physical host. Sustained ≥10 = your provider oversold the box — worth a complaint.',
  'monitor.tip.r': 'r — processes QUEUED for CPU (run queue). Only shown when it exceeds the core count = CPU can’t keep up.',
  'monitor.tip.swap': 'swap — MB of swap in use. RAM ran out so the system borrows disk as memory; things get visibly slow.',
  'monitor.tip.net': 'Network throughput: ↓ received / ↑ sent (all interfaces, loopback excluded).',
  'monitor.tip.conn': 'Open TCP connections (ESTABLISHED). A sudden spike usually means bots/scrapers.',
  'monitor.tip.inode': '% inodes used — running out means no new files even with free disk space. Shown at ≥70% only.',
  'monitor.tip.top': 'The process using the most CPU right now.',
  'monitor.tip.svc': 'Service uptime (time since the process last restarted) — different from the server uptime top-right: restarting a service doesn’t reset server uptime.',

