  'monitor.range1h': '1時間',
  'monitor.range24h': '24時間',
  'monitor.loadNorm': 'CPUあたり%',
  'monitor.historyInline': '1時間の履歴チャートをカード上に表示（もう一度クリックで閉じる）',
  'monitor.historyMore': '⤢ 詳細・24時間',
  'monitor.tip.load': '1 / 5 / 15 分のロードアベレージ。%はCPU数で正規化：100% = 全コアビジー。100%を超えることもあります。',
  'monitor.tip.cpu': '実際にビジーなCPU% = 100 − idle − iowait（2回のポーリング間の /proc/stat から算出）。',
  'monitor.tip.ram': '使用中RAM%（回収可能なキャッシュ/バッファは除外 — MemAvailable）。',
  'monitor.tip.disk': '最も使用率が高い実パーティション（tmpfs除外）。マウントポイントはラベル横に表示。',
  'monitor.tip.us': 'us — アプリケーションコード実行中のCPU%（user）。高い = アプリ自体がCPUを消費。',
  'monitor.tip.sy': 'sy — カーネル内のCPU%（system）：syscall、ネットワーク、I/O処理。異常に高い場合は接続/プロセス過多が多い。',
  'monitor.tip.wa': 'wa — ディスク待ちのCPU%（iowait）。高い = ディスクボトルネック（CPU不足ではない）。≥20で黄色。',
  'monitor.tip.st': 'st — ハイパーバイザーが同じ物理ホスト上の他VPSに奪ったCPU%（steal）。≥10が継続 = オーバーセル。プロバイダーに相談を。',
  'monitor.tip.r': 'r — CPU待ちのプロセス数（run queue）。コア数を超えた時のみ表示 = CPUが追いついていない。',
  'monitor.tip.swap': 'swap — 使用中スワップMB。RAM枯渇でディスクを代用中；動作が目に見えて遅くなる。',
  'monitor.tip.net': 'ネットワーク帯域：↓ 受信 / ↑ 送信（loopback以外の全インターフェース合計）。',
  'monitor.tip.conn': '確立済みTCP接続数（ESTABLISHED）。急増は通常ボット/スクレイパー。',
  'monitor.tip.inode': '使用中inode% — 枯渇するとディスクに空きがあってもファイルを作れない。≥70%でのみ表示。',
  'monitor.tip.top': '現在最もCPUを使っているプロセス。',
  'monitor.tip.svc': 'サービスの稼働時間（プロセスの最終再起動からの時間）— 右上のサーバー稼働時間とは別物：サービス再起動ではサーバー稼働時間はリセットされない。',

